return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n >= 2 && n <= 4) ? 1 : 2);','language'=>'sk_SK','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:51:08+00:00','po-revision-date'=>'2026-11-05T19:51:08+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Dopĺňa chýbajúce preklady pre pluginy a témy, ktoré sú už nainštalované na vašej stránke.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Táto obrazovka nahrávania je zastaraná: odvtedy sa pripravilo iné nahrávanie. Nič sa neodoslalo. Aktuálne nahrávanie skontrolujte zo zoznamu Translations.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Bezplatný servisný plán poskytuje každej stránke obmedzený počet slotov pre pluginy a témy; využité sloty sa zobrazia v Nastaveniach po aktivácii Babilim.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Požiadanie o preklad zaradí tento plugin alebo tému do jedného zo slotov bezplatného servisného plánu pre túto stránku (limit je %1$d pre témy a %2$d pre pluginy), ak ho ešte nemá. Slot zostáva využitý a neúspešný preklad ho neuvoľní.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Požiadanie o preklad zaradí tento plugin alebo tému do jedného zo slotov bezplatného servisného plánu pre túto stránku, ak ho ešte nemá. Slot zostáva využitý a neúspešný preklad ho neuvoľní.','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'Ak tento plugin alebo téma ešte nie je v jednom zo slotov bezplatného servisného plánu pre túto stránku, požiadanie o preklad ho do jedného zaradí (limit je %1$d pre témy a %2$d pre pluginy). Slot zostáva využitý a neúspešný preklad ho neuvoľní. Pokračovať?','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'Ak tento plugin alebo téma ešte nie je v jednom zo slotov bezplatného servisného plánu pre túto stránku, požiadanie o preklad ho do jedného zaradí. Slot zostáva využitý a neúspešný preklad ho neuvoľní. Pokračovať?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d stránka v tejto sieti je nastavená tak, že pri odstránení pluginu odstráni svoju identitu Babilim. Platenú licenciu pripojenú k tejto stránke by potom nebolo možné automaticky obnoviť; museli by ste sa obrátiť na podporu Babilim na %2$s. Ak chcete identitu zachovať, stlačte Zrušiť, v nastaveniach Babilim tejto stránky zrušte začiarknutie voľby "Pri odinštalovaní odstrániť všetky údaje Babilim" a deaktivujte znova. Napriek tomu deaktivovať?' . "\0" . '%1$d stránky v tejto sieti sú nastavené tak, že pri odstránení pluginu odstránia svoju identitu Babilim. Platenú licenciu pripojenú k týmto stránkam by potom nebolo možné automaticky obnoviť; museli by ste sa obrátiť na podporu Babilim na %2$s. Ak chcete identity zachovať, stlačte Zrušiť, v nastaveniach Babilim každej stránky zrušte začiarknutie voľby "Pri odinštalovaní odstrániť všetky údaje Babilim" a deaktivujte znova. Napriek tomu deaktivovať?' . "\0" . '%1$d stránok v tejto sieti je nastavených tak, že pri odstránení pluginu odstránia svoju identitu Babilim. Platenú licenciu pripojenú k týmto stránkam by potom nebolo možné automaticky obnoviť; museli by ste sa obrátiť na podporu Babilim na %2$s. Ak chcete identity zachovať, stlačte Zrušiť, v nastaveniach Babilim každej stránky zrušte začiarknutie voľby "Pri odinštalovaní odstrániť všetky údaje Babilim" a deaktivujte znova. Napriek tomu deaktivovať?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s nie je čo robiť.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Vyberte jazyk.','%d failed'=>'Zlyhalo: %d' . "\0" . 'Zlyhalo: %d' . "\0" . 'Zlyhalo: %d','%d not yet tried'=>'Zatiaľ nevyskúšané: %d' . "\0" . 'Zatiaľ nevyskúšané: %d' . "\0" . 'Zatiaľ nevyskúšané: %d','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d hlásenie čaká. „Vždy zdieľať“ a „Nezdieľať“ platia pre všetky.' . "\0" . '%d hlásenia čakajú. „Vždy zdieľať“ a „Nezdieľať“ platia pre všetky.' . "\0" . '%d hlásení čaká. „Vždy zdieľať“ a „Nezdieľať“ platia pre všetky.','%d skipped'=>'Preskočené: %d' . "\0" . 'Preskočené: %d' . "\0" . 'Preskočené: %d','%d succeeded'=>'Úspešné: %d' . "\0" . 'Úspešné: %d' . "\0" . 'Úspešné: %d','%d to install'=>'%d na inštaláciu' . "\0" . '%d na inštaláciu' . "\0" . '%d na inštaláciu','(a public key generated for this site)'=>'(verejný kľúč vygenerovaný pre túto lokalitu)','(detected)'=>'(zistené)','(generic codes and coordinates only)'=>'(iba všeobecné kódy a súradnice)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Vyčistenie bolo pozastavené dňa %1$s: %2$s. Nič nebolo odstránené.','A file in the component could not be read, so it was not packaged.'=>'Súbor v komponente sa nepodarilo prečítať, preto nebol zabalený.','A host that serves only one PHP request at a time cannot complete this step.'=>'Hosting, ktorý spracúva naraz iba jednu požiadavku PHP, tento krok nedokáže dokončiť.','A part of the upload kept failing, so the upload was cancelled.'=>'Časť nahrávania opakovane zlyhávala, preto bolo nahrávanie zrušené.','A translation cannot be requested for that locale on this site right now.'=>'Preklad pre túto lokalitu nie je možné na tejto stránke momentálne vyžiadať.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Zápis do indexu prekladov sa dňa %1$s (%2$s) dostal do konfliktu s inou požiadavkou a nebol použitý; ponechaná bola najnovšia verzia.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Zápis do indexu prekladov dňa %1$s (%2$s) sa nepodarilo dokončiť a nebol použitý (%3$s).','Account'=>'Účet','Add another language'=>'Pridať ďalší jazyk','Advanced'=>'Pokročilé','All'=>'Všetky','All free-plan slots for this site are used'=>'Všetky sloty bezplatného plánu pre tento web sú využité','All languages'=>'Všetky jazyky','Already in WordPress core'=>'Už v jadre WordPress','Already installed.'=>'Už nainštalované.','Always share'=>'Vždy zdieľať','Another installation is running; try again in a moment.'=>'Prebieha iná inštalácia; skúste to o chvíľu znova.','Automatic installs'=>'Automatické inštalácie','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Automatické inštalácie sú teraz vypnuté; ak ich chcete, znova ich zapnite v nastaveniach.','Available'=>'Dostupné','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Dostupné preklady je možné nainštalovať jedným kliknutím a chýbajúce si možno vyžiadať. Kým sú automatické inštalácie zapnuté, preklady, ktoré služba uvádza ako dostupné pre jazyky, ktoré spravujete, sa inštalujú počas synchronizácie dvakrát denne.','Available · %s'=>'Dostupné · %s','Babilim Settings'=>'Nastavenia Babilim','Babilim adds translations for every language checked here.'=>'Babilim pridáva preklady pre každý tu zaškrtnutý jazyk.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim nemohol potvrdiť dočasný priečinok mimo webu, preto komponent nebol zabalený a nič sa nenahralo. Definujte BABILIM_TEMP_DIR v wp-config.php ako zapisovateľný priečinok mimo koreňového adresára webu (napríklad priečinok vedľa verejného adresára vášho webu, nie v ňom) alebo ho vyžiadajte od svojho poskytovateľa hostingu.','Babilim could not finish checking this site.'=>'Babilim nemohol dokončiť kontrolu tejto stránky.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim nemohol dokončiť povolenie (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim nemohol dokončiť overenie tohto webu (služba sa k nemu nedokázala pripojiť späť). Registrácia je pozastavená.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim nemohol overiť túto stránku, preto sa nič nestiahne ani nenainštaluje, kým overenie nebude úspešné.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim nemohol overiť tento web, preto sa nič nesťahuje ani neinštaluje.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim nájde na tomto webe doplnky a témy, ktoré nemajú preklad pre váš jazyk, a pre každý z nich nainštaluje jeden.','Babilim has not been enabled for this site yet.'=>'Babilim ešte nebol pre tento web aktivovaný.','Babilim has not installed any translation for this language.'=>'Babilim nenainštaloval žiadny preklad pre tento jazyk.','Babilim hit an error. Share an error report?'=>'Babilim narazil na chybu. Zdieľať hlásenie o chybe?','Babilim installed %d translation automatically since your last visit.'=>'Babilim od vašej poslednej návštevy automaticky nainštaloval %d preklad.' . "\0" . 'Babilim od vašej poslednej návštevy automaticky nainštaloval %d preklady.' . "\0" . 'Babilim od vašej poslednej návštevy automaticky nainštaloval %d prekladov.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim je zakázaný. Nič sa už neodosiela; už nainštalované preklady naďalej fungujú.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim je povolený: táto stránka je overená a bol nájdený %d komponent.' . "\0" . 'Babilim je povolený: táto stránka je overená a boli nájdené %d komponenty.' . "\0" . 'Babilim je povolený: táto stránka je overená a bolo nájdených %d komponentov.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Prebieha povoľovanie služby Babilim a kontrola tohto webu… (posledný pokus: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Prebieha povoľovanie služby Babilim a kontrola tohto webu… Znova načítajte túto stránku alebo počkajte na dokončenie plánovanej kontroly.','Babilim is not enabled.'=>'Babilim nie je povolený.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim je nastavený tak, že pri odstránení pluginu odstráni identitu tejto stránky. Platenú licenciu pripojenú k tejto stránke by potom nebolo možné automaticky obnoviť; museli by ste sa obrátiť na podporu Babilim na %s. Ak chcete identitu zachovať, stlačte Zrušiť, v nastaveniach Babilim zrušte začiarknutie voľby "Pri odinštalovaní odstrániť všetky údaje Babilim" a deaktivujte znova. Napriek tomu deaktivovať?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim vyčerpal čas pre tento krok a bude pokračovať pri ďalšej kontrole.','Babilim settings'=>'Nastavenia Babilim','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Synchronizáciu Babilim služba dočasne oneskorila (obmedzenie počtu požiadaviek); skúsi to znova po %s.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim bol aktualizovaný, kým toto nahratie čakalo. Starý balík bol zahodený; potvrďte nahratie znova.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim nahrá tieto súbory z %1$s (verzia %2$s): každý súbor .php a .js, každý súbor block.json a súbory readme.txt, readme.md, style.css a theme.json v jeho hlavnom priečinku. Používajú sa na nájdenie textu, ktorý treba preložiť, a na identifikáciu doplnku alebo motívu.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest nie je k dispozícii: %s','Back'=>'Späť','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Kúpili ste už licenciu pre túto doménu? Zadajte kód na obnovenie, ktorý ste dostali pri pokladni.','Broken placeholder'=>'Pokazený zástupný symbol','Build'=>'Zostavenie','Built'=>'Zostavené','Bulk actions apply only to the selected language of each selected component.'=>'Hromadné akcie sa vzťahujú iba na vybraný jazyk každého vybraného komponentu.','Bulk actions apply to every matching language of each selected component.'=>'Hromadné akcie sa vzťahujú na každý zodpovedajúci jazyk každého vybraného komponentu.','Bulk download:'=>'Hromadné sťahovanie:','Bulk request:'=>'Hromadná žiadosť:','Bulk update:'=>'Hromadná aktualizácia:','Bundled with the plugin'=>'Súčasť pluginu','Bundled with the theme'=>'Súčasť témy','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Kliknutím na Povoliť súhlasíte s odoslaním vyššie uvedených informácií službe Babilim.','By continuing you confirm that you have the right to upload this component.'=>'Pokračovaním potvrdzujete, že máte právo nahrať tento komponent.','Cancel'=>'Zrušiť','Category'=>'Kategória','Check again'=>'Skontrolovať znova','Check again now'=>'Skontrolovať znova teraz','Checkout is not available for this site right now.'=>'Pokladňa nie je pre tento web momentálne k dispozícii.','Choose'=>'Vybrať','Choose a category…'=>'Vyberte kategóriu…','Choose a language'=>'Vyberte jazyk','Choose a language…'=>'Vyberte jazyk…','Clear filters'=>'Vymazať filtre','Close'=>'Zavrieť','Component'=>'Komponent','Confirm'=>'Potvrdiť','Conflicting keys'=>'Konfliktné kľúče','Continue'=>'Pokračovať','Continue next batch (%d left)'=>'Pokračovať ďalšou dávkou (zostáva %d)','Continuing…'=>'Pokračuje sa…','Could not back up %s before replacing it.'=>'Nepodarilo sa zálohovať %s pred jeho nahradením.','Could not create the package archive.'=>'Nepodarilo sa vytvoriť archív balíka.','Could not determine active components; the existing merged index was left unchanged.'=>'Nepodarilo sa zistiť aktívne komponenty; existujúci zlúčený index zostal nezmenený.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Nepodarilo sa zistiť nainštalované doplnky/témy; vyčistenie bolo preskočené, nič sa neodstránilo.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Nepodarilo sa načítať úplný zoznam lokalít WordPress.org zo služby, preto momentálne nemožno pridať žiadny ďalší jazyk.','Could not move %s into place.'=>'Nepodarilo sa presunúť %s na miesto.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Zlúčený index pre \'%s\' sa nepodarilo presunúť na miesto; predchádzajúci poskytovaný index (ak existoval) bol odstránený, aby nezostal polovične aktualizovaný. Pre túto lokalitu sa nebude poskytovať žiadny doplnok predvolenej domény, kým nebude nasledujúce zostavenie úspešné.','Could not open zip: %s'=>'Nepodarilo sa otvoriť zip: %s','Could not prepare %s for rollback.'=>'Súbor %s sa nepodarilo pripraviť na vrátenie zmien.','Could not read %s back after moving it into place.'=>'Súbor %s sa po presune na miesto nepodarilo znova prečítať.','Could not read: %s'=>'Nepodarilo sa prečítať: %s','Could not restore the purchase: %s'=>'Nákup sa nepodarilo obnoviť: %s','Could not show a new restore code: %s'=>'Nepodarilo sa zobraziť nový kód na obnovenie: %s','Could not stage %s'=>'Nepodarilo sa pripraviť %s','Could not stage default/%s'=>'Nepodarilo sa pripraviť default/%s','Could not start checkout: %s'=>'Nepodarilo sa spustiť pokladňu: %s','Could not verify entry count for %s'=>'Nepodarilo sa overiť počet záznamov pre %s','Could not write the downloaded package to disk.'=>'Stiahnutý balík sa nepodarilo zapísať na disk.','Could not write the staged merged index.'=>'Pripravený zlúčený index sa nepodarilo zapísať.','Current translation'=>'Aktuálny preklad','Custom overrides'=>'Vlastné prepísania','Danger zone'=>'Nebezpečná zóna','Default supplement entry count mismatch.'=>'Nezhoda počtu záznamov predvoleného doplnku.','Delete all Babilim data on uninstall'=>'Pri odinštalovaní odstrániť všetky údaje Babilim','Disable Babilim'=>'Vypnúť Babilim','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Vypnúť Babilim? Nainštalované preklady zostanú zachované, ale nebudú sa vykonávať ďalšie kontroly ani sťahovanie.','Don\'t share'=>'Nezdieľať','Download'=>'Stiahnuť','Downloaded and installed.'=>'Stiahnuté a nainštalované.','Downloading…'=>'Sťahuje sa…','Downloads: %1$d/%2$d (%3$s)'=>'Stiahnutia: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Príspevok každého komponentu do doplnku predvolenej domény každej lokality.','Enable Babilim'=>'Povoliť Babilim','Enabling…'=>'Povoľuje sa…','English (United States)'=>'Angličtina (Spojené štáty)','Entries'=>'Záznamy','Entry count mismatch for %s'=>'Nezhoda počtu záznamov pre %s','Error reports'=>'Hlásenia o chybách','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Každý nainštalovaný doplnok alebo téma: slug, verzia, textové domény, informácia o tom, či je doplnok alebo téma v adresári wp.org, pribalené lokality a lokality, pre ktoré ste už nainštalovali preklad od Babilim.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Každá lokalita používaná na tejto stránke (lokalita stránky, nainštalované jazykové balíky, lokality používateľov a všetky, ktoré pridáte ručne). Žiadna lokalita nie je posudzovaná inak ako ostatné.','Excluded'=>'Vylúčené','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Súbory s inými názvami alebo príponami sa nezahŕňajú, rovnako ako priečinky uploads, cache, logs, backup, data, vendor, node_modules a languages, skryté súbory ani súbory, ktorých názvy zodpovedajú bežným citlivým údajom (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Súbory s kódom môžu stále obsahovať text alebo dáta, ktoré by ste nechceli zdieľať; ak si nie ste istí, skontrolujte ich. Služba po prijatí odstráni rovnaké druhy súborov ešte raz.','Free'=>'Zadarmo','Free-plan slots'=>'Sloty bezplatného plánu','General'=>'Všeobecné','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Ak je táto voľba zapnutá, odinštalovaním sa odstráni aj identita Babilim tejto stránky. Platenú licenciu pripojenú k tejto stránke potom nebude možné automaticky obnoviť; museli by ste sa na podporu Babilim obrátiť na %s.','Included'=>'Zahrnuté','Included in index'=>'Zahrnuté v indexe','Install available translations automatically'=>'Automaticky inštalovať dostupné preklady','Installed'=>'Nainštalované','Installed translations are kept, but no further checks or downloads will run.'=>'Nainštalované preklady zostanú zachované, ale nebudú sa vykonávať ďalšie kontroly ani sťahovanie.','Installed · %s'=>'Nainštalované · %s','Installed · built for %1$s, this site has %2$s'=>'Nainštalované · vytvorené pre %1$s, tento web má %2$s','Installed · built for %s'=>'Nainštalované · vytvorené pre %s','Installed · built for %s, all free-plan slots for this site are used'=>'Nainštalované · vytvorené pre %s, všetky sloty bezplatného plánu pre tento web sú využité','Installed · built for %s, new version failed'=>'Nainštalované · zostavené pre %s, nová verzia zlyhala','Installed · built for %s, new version not covered by the free service plan'=>'Nainštalované · vytvorené pre %s, nová verzia nie je zahrnutá v bezplatnom servisnom pláne','Installed · built for %s, new version scheduled'=>'Nainštalované · vytvorené pre %s, nová verzia je naplánovaná','Installed · built for %s, translating the new version…'=>'Nainštalované · vytvorené pre %s, prekladá sa nová verzia…','Installed · built for a different version'=>'Nainštalované · vytvorené pre inú verziu','Installed · built for a different version, all free-plan slots for this site are used'=>'Nainštalované · vytvorené pre inú verziu, všetky sloty bezplatného plánu pre tento web sú využité','Installed · built for a different version, new version failed'=>'Nainštalované · zostavené pre inú verziu, nová verzia zlyhala','Installed · built for a different version, new version not covered by the free service plan'=>'Nainštalované · vytvorené pre inú verziu, nová verzia nie je zahrnutá v bezplatnom servisnom pláne','Installed · built for a different version, new version scheduled'=>'Nainštalované · vytvorené pre inú verziu, nová verzia je naplánovaná','Installed · built for a different version, translating the new version…'=>'Nainštalované · vytvorené pre inú verziu, prekladá sa nová verzia…','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Ukladá ich hostingový poskytovateľ služby a na vytvorenie prekladu ich spracúvajú modely umelej inteligencie.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Zachovať moje vlastné prepísania prekladov pri úplnom vymazaní alebo odinštalovaní tohto pluginu.','Language'=>'Jazyk','Language:'=>'Jazyk:','Languages'=>'Jazyky','Languages found on this site: %s.'=>'Jazyky nájdené na tomto webe: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Posledné vyčistenie %1$s: novo označených %2$d, odstránených súborov %3$d, odstránených záznamov %4$d.','Maintenance'=>'Údržba','Maintenance status is not available right now.'=>'Stav údržby momentálne nie je k dispozícii.','Manifest unavailable: %s'=>'Manifest nie je k dispozícii: %s','Negation reversed'=>'Obrátený zápor','No'=>'Nie','No build is available to download for this locale.'=>'Pre túto lokalitu nie je k dispozícii žiadna zostava na stiahnutie.','No cleanup has run yet.'=>'Zatiaľ nebolo spustené žiadne vyčistenie.','No components match these filters. %s'=>'Týmto filtrom nezodpovedá žiadny komponent. %s','No components synced yet.'=>'Zatiaľ neboli synchronizované žiadne komponenty.','No installed translation matches.'=>'Nezodpovedá žiadny nainštalovaný preklad.','No language is managed yet.'=>'Zatiaľ nie je spravovaný žiadny jazyk.','No pending challenge for this nonce.'=>'Pre tento nonce nie je v očakávaní žiadna výzva.','No pending challenge to verify.'=>'Nie je žiadna čakajúca výzva na overenie.','No plugins or themes found.'=>'Nenašli sa žiadne pluginy ani témy.','No previous build to roll back to.'=>'Neexistuje predchádzajúce zostavenie, na ktoré by sa dalo vrátiť.','No record for %s'=>'Žiadny záznam pre %s','No site id is on file to rotate a token for.'=>'Nie je uložené žiadne ID stránky, pre ktoré by sa dal obmeniť token.','No — component inactive'=>'Nie — komponent je neaktívny','No — component removed'=>'Nie — komponent bol odstránený','No — installed version differs from the active one'=>'Nie – nainštalovaná verzia sa líši od aktívnej','Not a valid server_build_id: %s'=>'Neplatný server_build_id: %s','Not covered by the free service plan'=>'Nie je zahrnuté v bezplatnom servisnom pláne','Not installed'=>'Nenainštalované','Not registered yet'=>'Zatiaľ nezaregistrované','Not supported'=>'Nepodporované','Not verified'=>'Neoverené','Note (optional)'=>'Poznámka (voliteľné)','Nothing to choose.'=>'Nie je z čoho vyberať.','Nothing to confirm.'=>'Nie je čo potvrdiť.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Predvolene vypnuté: odstránenie pluginu zachová identitu tohto webu, takže ju možno pri opätovnej inštalácii znovu použiť.','One or more served files no longer match the manifest.'=>'Jeden alebo viac poskytovaných súborov už nezodpovedá manifestu.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Jednorazový nákup pre tento web: %1$s %2$s. Zahŕňa všetky budúce aktualizácie prekladov. Platbu spracúva Paddle na novej karte.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Toto môže urobiť iba správca siete, pretože sa tým menia súbory prekladov zdieľané všetkými webmi v tejto sieti.','Only plugins and themes can be packaged.'=>'Zabaliť možno iba pluginy a témy.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Iba keď potvrdíte nahratie doplnku alebo motívu, ktorý nie je na WordPress.org: každý súbor .php a .js, každý súbor block.json a súbory readme.txt, readme.md, style.css a theme.json v hlavnom priečinku daného komponentu, ako zip, po vynechaní súborov zodpovedajúcich bežným citlivým údajom.','Open Babilim settings'=>'Otvoriť nastavenia Babilim','Original language'=>'Pôvodný jazyk','Original string'=>'Pôvodný reťazec','Paid'=>'Platené','Partner'=>'Partner','Please check that your site can be reached from the internet, then try again.'=>'Skontrolujte, či je váš web dostupný z internetu, a skúste to znova.','Please choose a category for this report.'=>'Vyberte kategóriu pre toto hlásenie.','Plugin'=>'Plugin','Plugin · %s'=>'Plugin · %s','Plugins'=>'Pluginy','Preview'=>'Náhľad','Purchase restored. This site is now licensed.'=>'Nákup bol obnovený. Tento web je teraz licencovaný.','Re-parsed entry count did not match the built index.'=>'Počet záznamov po opätovnom spracovaní nezodpovedá zostavenému indexu.','Re-verify'=>'Overiť znova','Rebuild index now'=>'Znova zostaviť index','Refusing to write outside the Babilim language-file directory.'=>'Zápis mimo adresára jazykových súborov Babilim sa odmieta.','Registration response was missing required fields.'=>'V odpovedi na registráciu chýbali povinné polia.','Registration restarted.'=>'Registrácia sa spustila znova.','Remove'=>'Odstrániť','Remove everything Babilim installed'=>'Odstrániť všetko, čo Babilim nainštaloval','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Odstrániť všetko, čo Babilim nainštaloval? Týmto odstránite všetky jazykové súbory, ktoré Babilim nainštaloval pre všetky pluginy a témy na tomto webe.','Remove the %2$s translation of %1$s from this site?'=>'Odstrániť preklad %2$s pre %1$s z tejto stránky?','Removed %d installed component.'=>'Odstránený %d nainštalovaný komponent.' . "\0" . 'Odstránené %d nainštalované komponenty.' . "\0" . 'Odstránených %d nainštalovaných komponentov.','Removed after a failed integrity check'=>'Odstránené po neúspešnej kontrole integrity','Removed.'=>'Odstránené.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Odstráni všetky jazykové súbory, ktoré Babilim nainštaloval pre všetky pluginy a témy na tomto webe.','Report a problem'=>'Nahlásiť problém','Report translation'=>'Nahlásiť preklad','Request newer translation'=>'Požiadať o novší preklad','Request translation'=>'Požiadať o preklad','Requestable'=>'Možno požiadať o preklad','Requesting…'=>'Odosiela sa žiadosť…','Restart registration'=>'Reštartovať registráciu','Restore code'=>'Kód na obnovenie','Restore purchase'=>'Obnoviť nákup','Retry request'=>'Zopakovať žiadosť','Roll back'=>'Vrátiť späť','Roll back and report'=>'Vrátiť späť a nahlásiť','Roll back and send report'=>'Vrátiť späť a odoslať hlásenie','Roll back the %2$s translation of %1$s to the previous build?'=>'Vrátiť preklad %2$s komponentu %1$s na predchádzajúce zostavenie?','Rolled back and reported.'=>'Zmeny vrátené a nahlásené.','Rolled back to the previous build.'=>'Zmeny vrátené na predchádzajúcu zostavu.','Rolled back, but the report could not be sent: %s'=>'Zmeny vrátené, ale hlásenie sa nepodarilo odoslať: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Vrátenie späť by prepísalo \'%1$s\' (%2$s), ktorý sa teraz poskytuje pre iný nainštalovaný komponent (%3$s); nič sa nezmenilo.','Rotate-token response was missing site_token.'=>'V odpovedi na výmenu tokenu chýbal site_token.','Save changes'=>'Uložiť zmeny','Scheduled, waiting to be processed'=>'Naplánované, čaká na spracovanie','Search'=>'Hľadať','Search components'=>'Hľadať komponenty','Search the installed translations'=>'Hľadať v nainštalovaných prekladoch','Select all'=>'Vybrať všetko','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Vyberte menej komponentov: najviac %1$d operácií na jedno spustenie (vybrali ste %2$d).','Send report'=>'Odoslať hlásenie','Service plan'=>'Servisný plán','Settings'=>'Nastavenia','Share error reports'=>'Zdieľať hlásenia o chybách','Share this report'=>'Zdieľať toto hlásenie','Show a new restore code'=>'Zobraziť nový kód na obnovenie','Show the "Report translation" entry in the admin toolbar'=>'Zobraziť položku „Nahlásiť preklad“ v administračnom paneli nástrojov','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Časť textu tohto komponentu je pevne zakódovaná jeho autorom a jazykový balík ju nemôže preložiť.','Status'=>'Stav','Status unknown'=>'Stav neznámy','String context'=>'Kontext reťazca','Suggested translation'=>'Navrhovaný preklad','Supplementary translation index'=>'Doplnkový index prekladov','Supplementary translation index rebuilt.'=>'Doplnkový index prekladov bol znova zostavený.','Supplementary translation maintenance'=>'Údržba doplnkových prekladov','Supplementary translations'=>'Doplnkové preklady','Sweep aborted without orphaning anything: %s.'=>'Čistenie bolo prerušené bez toho, aby sa čokoľvek označilo ako osirelé: %s.','Sweep complete: %d file deleted.'=>'Skenovanie dokončené: %d súbor odstránený.' . "\0" . 'Skenovanie dokončené: %d súbory odstránené.' . "\0" . 'Skenovanie dokončené: %d súborov odstránených.','Sweep now'=>'Preskenovať teraz','Sync complete.'=>'Synchronizácia dokončená.','Thank you. Your report was sent.'=>'Ďakujeme. Vaše hlásenie bolo odoslané.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Tento komponent nie je na tejto stránke nainštalovaný, preto preň nie je možné požiadať o preklad.','That does not look like a restore code.'=>'Toto nevyzerá ako kód na obnovenie.','That is not a valid WordPress locale code. Nothing was saved.'=>'Toto nie je platný kód lokality WordPress. Nič sa neuložilo.','That is not a valid build identifier.'=>'Toto nie je platný identifikátor zostavenia.','The change could not be recorded in the translation index; please try again.'=>'Zmenu sa nepodarilo zaznamenať do indexu prekladov; skúste to prosím znova.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Čistenie prebehlo, ale niektoré jeho zmeny sa nepodarilo zaznamenať do indexu prekladov; nasledujúce čistenie ich skúsi znova.','The component has no files that can be uploaded.'=>'Komponent nemá žiadne súbory, ktoré možno nahrať.','The component is not inside the plugins or themes directory.'=>'Komponent sa nenachádza v adresári zásuvných modulov ani motívov.','The component\'s main file was not found.'=>'Hlavný súbor komponentu sa nenašiel.','The download response was missing a usable location.'=>'V odpovedi na stiahnutie chýbalo použiteľné umiestnenie.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Položka otvorí panel na vyhľadávanie prekladov, ktoré Babilim nainštaloval na tomto webe, a na nahlásenie jedného z nich.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Pole „%1$s“ je príliš dlhé: má %2$d znakov a limit je %3$d. Nič sa neodoslalo; skráťte ho a skúste to znova.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Zadaná doména \'%1$s\' nezodpovedá ani vlastnému slugu v manifeste balíka \'%2$s\', ani jeho text_domain \'%3$s\'.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Zlúčený index pre \'%s\' bol znovu zostavený, ale index prekladov ho nedokázal zaznamenať; nasledujúce zostavenie to skúsi znova.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Pôvodný text a z neho vytvorené preklady budú poskytnuté ďalším webom, ktoré nainštalujú rovnakú verziu.','The package declares no main translation file.'=>'Balík nedeklaruje žiadny hlavný súbor prekladu.','The package has no %s for its own text domain.'=>'Balík neobsahuje súbor %s pre vlastnú textovú doménu.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Druh \'%1$s\' v manifeste balíka nezodpovedá požadovanému druhu \'%2$s\'.','The package produced no servable main translation file.'=>'Balík nevytvoril žiadny použiteľný hlavný súbor prekladu.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Textová doména balíka \'%1$s\' nezodpovedá kópii komponentu na tomto webe (\'%2$s\'), preto balík nebol nainštalovaný.','The packaged component could not be read.'=>'Zabalený komponent sa nepodarilo prečítať.','The registration challenge is not in the expected form.'=>'Registračná výzva nemá očakávaný tvar.','The report could not be sent.'=>'Hlásenie sa nepodarilo odoslať.','The search could not be completed.'=>'Vyhľadávanie sa nepodarilo dokončiť.','The service asked this site to wait before syncing again.'=>'Služba požiadala túto stránku, aby pred ďalšou synchronizáciou počkala.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Služba sa nemohla spojiť s vašou stránkou. Požiadavku pravdepodobne blokuje firewall, bezpečnostný plugin alebo pravidlo hostingu; povoľte prosím požiadavky na /wp-json/babilim/v1/challenge.','The service\'s upload offer was incomplete.'=>'Ponuka nahrávania zo služby bola neúplná.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Textová doména \'%1$s\' (%2$s) sa už poskytuje pre iný nainštalovaný komponent (%3$s); nič sa nenainštalovalo.','The upload is kept until you ask Babilim to delete it.'=>'Nahraté dáta sa uchovávajú, kým Babilim nepožiadate o ich odstránenie.','Theme'=>'Motív','Theme · %s'=>'Téma · %s','Themes'=>'Témy','There is no upload in progress.'=>'Nahrávanie momentálne neprebieha.','There is no upload waiting for confirmation.'=>'Nečaká žiadne nahrávanie na potvrdenie.','These are the languages this site uses. You can change them in %s.'=>'Toto sú jazyky, ktoré tento web používa. Môžete ich zmeniť v %s.','These fields will be sent:'=>'Odošlú sa tieto polia:','This build is not one this site currently knows about for this component/locale.'=>'Túto zostavu táto stránka v súčasnosti pre tento komponent a lokalitu nepozná.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Tento komponent neuvádza číslo verzie, preto preň nie je možné požiadať o preklad.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Tento komponent je väčší, než služba akceptuje, preto sa nedá nahrať.','This component was already uploaded. Babilim is checking it now.'=>'Tento komponent už bol nahraný. Babilim ho teraz kontroluje.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Číslo verzie tohto komponentu je dlhšie ako %d znakov, čo Babilim nedokáže spracovať, preto preň nie je možné požiadať o preklad.','This issues a new restore code and the previous one stops working. Continue?'=>'Tým sa vydá nový kód na obnovenie a predchádzajúci prestane fungovať. Pokračovať?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Táto sieť má príliš veľa stránok na kontrolu jednej po druhej a niektoré z nich môžu byť nastavené tak, že pri odstránení pluginu odstránia svoju identitu Babilim. Platenú licenciu pripojenú k takej stránke by potom nebolo možné automaticky obnoviť; museli by ste sa obrátiť na podporu Babilim na %s. Ak chcete identity zachovať, stlačte Zrušiť, v nastaveniach Babilim každej stránky zrušte začiarknutie voľby "Pri odinštalovaní odstrániť všetky údaje Babilim" a deaktivujte znova. Napriek tomu deaktivovať?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Verzia tohto doplnku, aby vám služba mohla odporučiť aktualizáciu, ak je príliš stará na komunikáciu.','This report does not name a valid plugin or theme and locale.'=>'Toto hlásenie neuvádza platný plugin alebo tému a lokalitu.','This report does not name an installed string.'=>'Táto správa neuvádza žiadny nainštalovaný reťazec.','This report is missing a valid build to report against.'=>'Tomuto hláseniu chýba platná zostava, ku ktorej sa vzťahuje.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Toto hlásenie bude zverejnené na GitHub a tretie strany si ho môžu ponechať.','This restore code was not recognised for this site.'=>'Tento kód na obnovenie nebol pre túto stránku rozpoznaný.','This site already has an active registration that can no longer be recovered automatically.'=>'Tento web už má aktívnu registráciu, ktorú už nie je možné automaticky obnoviť.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Táto stránka má %1$d komponentov v %2$d jazykoch, čo vyžaduje %3$d dávok kontroly; Babilim ich dokáže spracovať najviac %4$d za jedno spustenie. Znížte počet spravovaných jazykov v časti Nastavenia alebo deaktivujte nepoužívané zásuvné moduly a motívy, potom teraz stlačte Skontrolovať znova.','This site has no purchase to show a code for.'=>'Tento web nemá žiadny nákup, pre ktorý by sa dal zobraziť kód.','This site is already licensed. Reload the page.'=>'Tento web už má licenciu. Obnovte stránku.','This site is not registered with Babilim yet.'=>'Tento web ešte nie je zaregistrovaný v službe Babilim.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Tento web presahuje veľkosť, ktorú služba akceptuje pri jednej synchronizácii, preto boli niektoré položky vynechané: komponenty: %1$d a jazykové verzie: %2$d.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Tento web je súčasťou siete multisite, ktorá neinštaluje nové preklady automaticky. Už nainštalované preklady sa naďalej aktualizujú.','This site is verified.'=>'Tento web je overený.','This site must be verified first.'=>'Tento web musí byť najprv overený.','This site\'s URL, so the service can verify you own it.'=>'URL adresa tejto lokality, aby služba mohla overiť, že ju vlastníte.','This site\'s address is too long for Babilim to register.'=>'Adresa tejto stránky je príliš dlhá na registráciu v Babilim.','This site\'s configured locale.'=>'Nakonfigurovaná lokalita tejto stránky.','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Verejný kľúč inštalácie tejto lokality, ktorý slúži na preukázanie, že požiadavky skutočne pochádzajú z tejto lokality. Odosiela sa iba verejná časť.','This site\'s locale code is not one Babilim can register.'=>'Kód lokality tejto stránky nie je kód, ktorý Babilim dokáže zaregistrovať.','This string can\'t be reported from this site.'=>'Tento reťazec nie je možné z tohto webu nahlásiť.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Tento reťazec nie je medzi prekladmi nainštalovanými na tomto webe. Vyhľadajte znova a vyberte ho zo zoznamu.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Tento preklad bol od vášho vyhľadávania aktualizovaný. Vyhľadajte znova a vyberte reťazec z nového zoznamu.','To translate this component, Babilim needs its source.'=>'Na preklad tohto komponentu potrebuje Babilim jeho zdrojový kód.','Too many attempts. Try again tomorrow.'=>'Príliš veľa pokusov. Skúste to znova zajtra.','Too many reports today. Try again tomorrow.'=>'Dnes je príliš veľa hlásení. Skúste to znova zajtra.','Too many requests.'=>'Príliš veľa požiadaviek.','Toolbar'=>'Panel nástrojov','Translating…'=>'Prekladá sa…','Translation does not load'=>'Preklad sa nenačíta','Translation failed'=>'Preklad zlyhal','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Súbory prekladov, ktoré umiestnite do %s, majú vždy prednosť pred súbormi Babilim. Zostanú zachované, kým toto políčko nezrušíte.','Translation requested.'=>'Preklad bol vyžiadaný.','Translations'=>'Preklady','Type'=>'Typ','Type at least 2 characters to search.'=>'Ak chcete vyhľadávať, zadajte aspoň 2 znaky.','Unexpected HTTP %d response.'=>'Neočakávaná odpoveď HTTP %d.','Uninstall'=>'Odinštalovanie','Unknown kind: %s'=>'Neznámy druh: %s','Unsafe domain: %s'=>'Nebezpečná doména: %s','Unsafe locale: %s'=>'Nebezpečná lokalita: %s','Unsafe slug: %s'=>'Nebezpečný slug: %s','Unsafe text_domain: %s'=>'Nebezpečný text_domain: %s','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Až 20 čakajúcich diagnostických udalostí (napr. súbor, ktorý neprešiel kontrolou integrity), každá obsahuje iba kód, komponent a lokalitu, nikdy žiadny obsah reťazcov ani preložený text.','Update'=>'Aktualizovať','Update available'=>'Dostupná aktualizácia','Updates'=>'Aktualizácie','Updating…'=>'Aktualizuje sa…','Upgrade this site'=>'Povýšiť tento web','Upload and request'=>'Nahrať a požiadať','Upload cancelled.'=>'Nahrávanie zrušené.','Upload complete — translation requested.'=>'Nahrávanie dokončené – preklad bol vyžiadaný.','Upload expired before it finished'=>'Platnosť nahrávania vypršala pred jeho dokončením','Upload in progress — continue or cancel'=>'Prebieha nahrávanie — pokračujte alebo zrušte','Upload this component?'=>'Nahrať tento komponent?','Upload was not accepted'=>'Nahrávanie nebolo prijaté','Uploading'=>'Nahrávanie','Uploading part %1$d of %2$d…'=>'Nahráva sa časť %1$d z %2$d…','Uploading…'=>'Nahrávanie…','Verified'=>'Overené','Verify response was missing site_token.'=>'V odpovedi na overenie chýbal site_token.','Version %s'=>'Verzia %s','What is sent when Babilim checks this site'=>'Čo sa odosiela, keď Babilim kontroluje tento web','What is sent when you enable Babilim'=>'Čo sa odosiela pri povolení Babilim','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Keď v Babilim niečo zlyhá, odošle sa hlásenie o chybe službe Babilim, aby mohlo byť zverejnené ako verejný problém na GitHub. Hlásenie sa odošle ako pochádzajúce z tohto webu, s rovnakým overením ako každá iná požiadavka na službu Babilim. Služba zverejní ako verejný problém na GitHub iba kód chyby a verzie; verejný problém neobsahuje adresu webu, obsah ani cesty k súborom. Predvolene vypnuté.','Where you saw this (optional)'=>'Kde ste to videli (voliteľné)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Kým je táto možnosť zapnutá, preklady, ktoré služba uvádza ako dostupné pre jazyky, ktoré spravujete, sa inštalujú počas synchronizácie dvakrát denne.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Nesprávne pre tento kontext','Wrong meaning'=>'Nesprávny význam','Wrong plural form'=>'Nesprávny tvar množného čísla','Wrong term'=>'Nesprávny termín','Yes'=>'Áno','You are not allowed to do this.'=>'Na túto akciu nemáte oprávnenie.','Your PHP version, for compatibility.'=>'Vaša verzia PHP kvôli kompatibilite.','Your WordPress version, to serve compatible translation files.'=>'Vaša verzia WordPress na poskytovanie kompatibilných prekladových súborov.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Váš nový kód na obnovenie: %s. Uložte si ho na bezpečné miesto — predchádzajúci kód už nefunguje.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Vaše hlásenie sa automaticky spracúva modelmi AI a môže zlepšiť tento preklad pre iné weby.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Vaša stránka odpovedala, ale nie podľa očakávania. REST API môže byť prepísané iným pluginom alebo môže byť tento koncový bod ukladaný do vyrovnávacej pamäte; vylúčte prosím /wp-json/babilim/v1/challenge z ukladania do vyrovnávacej pamäte a prepisovania.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Váš web odpovedal príliš dlho. Skúste to prosím neskôr a skontrolujte, či hosting nie je príliš pomalý alebo preťažený.','Zip has no manifest.json.'=>'Archív zip neobsahuje manifest.json.','Zip is missing expected default file: %s'=>'V archíve zip chýba očakávaný predvolený súbor: %s','Zip is missing expected file: %s'=>'V archíve zip chýba očakávaný súbor: %s','_manifest.json has an unexpected structure'=>'Súbor _manifest.json má neočakávanú štruktúru','could not read _manifest.json: %s'=>'nepodarilo sa prečítať _manifest.json: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'V expected_manifest chýba pole \'%s\' alebo je neplatné.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'Pole \'server_build_id\' v expected_manifest nie je platné ID zostavenia.','failed to parse _manifest.json: %s'=>'Nepodarilo sa spracovať _manifest.json: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'osirelými by sa stalo %1$d z %2$d spravovaných komponentov (viac ako polovica)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'osirelým by sa stal každý spravovaný komponent typu %1$s (%2$d z %2$d)','l10n.php entry count mismatch for %s'=>'Nezhoda počtu záznamov l10n.php pre %s','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json obsahuje neplatné pole \'default_domain_entries\'.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json obsahuje neplatné pole \'default_domain_files\'.','manifest.json in the zip is not valid JSON.'=>'manifest.json v archíve zip nie je platný JSON.','manifest.json is missing or has an invalid \'%s\'.'=>'V manifest.json chýba pole \'%s\' alebo je neplatné.','manifest.json is missing or has an invalid \'build_no\'.'=>'V manifest.json chýba pole \'build_no\' alebo je neplatné.','manifest.json is missing or has an invalid \'entries\'.'=>'V manifest.json chýba pole \'entries\' alebo je neplatné.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'V manifest.json chýba pole \'extra_domains\' alebo je neplatné.','manifest.json is missing or has an invalid \'files\'.'=>'V manifest.json chýba pole \'files\' alebo je neplatné.','manifest.json\'s \'%s\' does not match the expected value.'=>'Pole \'%s\' v manifest.json nezodpovedá očakávanej hodnote.','manifest.json\'s \'contract\' is not a valid version string.'=>'Pole \'contract\' v manifest.json nie je platný reťazec verzie.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'Pole \'kind\' v manifest.json musí mať hodnotu \'plugin\' alebo \'theme\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'Pole \'server_build_id\' v manifest.json nie je platné ID zostavenia.','manifest.json\'s \'status\' must be \'published\'.'=>'Stav v manifest.json (\'status\') musí byť \'published\'.','nonce must be a hexadecimal string.'=>'Hodnota nonce musí byť hexadecimálny reťazec.','per day'=>'za deň','rc_…'=>'rc_…','sha256 mismatch for %s'=>'Nezhoda sha256 pre %s','sha256 mismatch for default/%s'=>'Nezhoda sha256 pre default/%s','component kind in the sweep brake messageplugin'=>'plugin','component kind in the sweep brake messagetheme'=>'motív','problem report categoryOther'=>'Iné','translation statusAvailable'=>'Dostupné','translation statusInstalled'=>'Nainštalované']];